                target.writeUTF(record);
            }

            @Override
            public String deserialize(String reuse, java.io.DataInput source) throws IOException {
                return source.readUTF();
            }

            @Override
            public String deserialize(java.io.DataInput source) throws IOException {
                return source.readUTF();
            }

