    }
    checkArgument(keyPositions.length > 0, "Grouping fields can not be empty at this point");
    // extract key field types
    CompositeType<T> cType = ((CompositeType<T>) (type));
    this.keyFields = new ArrayList<>(type.getTotalFields());
