        // Second write - should reuse existing ObjectOutputStream (put already called)
        output.clear();
        serializer.write(kryo, output, testObject);

        // Clean up
        output.close();
    }

    // Inner class matching the serializer type from the provided method
    private static class JavaSerializer<T> {
        @SuppressWarnings({ "unchecked", "rawtypes" })
        public void write(Kryo kryo, Output output, T o) {
            try {
                ObjectMap graphContext = kryo.getGraphContext();
                ObjectOutputStream objectStream = ((ObjectOutputStream) (graphContext.get(this)));
                if (objectStream == null) {
                    objectStream = new ObjectOutputStream(output);
                    graphContext.put(this, objectStream);
                }
                objectStream.writeObject(o);
                objectStream.flush();
            } catch (Exception ex) {
                throw new com.esotericsoftware.kryo.KryoException("Error during Java serialization.", ex);
            }
        }
    }

