package org.apache.flink.api.java.typeutils.runtime;

import com.esotericsoftware.kryo.KryoException;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

class NoFetchingInputread_KryoExceptionmethodFikaTest {

    @Test
    void testReadThrowsKryoException() throws Exception {
        InputStream throwingStream = new InputStream() {
            @Override
            public int read(byte[] b, int off, int len) throws IOException {
                throw new IOException("Test IOException");
            }

            @Override
            public int read() throws IOException {
                return -1;
            }
        };

        NoFetchingInput input = new NoFetchingInput(throwingStream);
        byte[] buffer = new byte[10];

        try {
            input.read(buffer, 0, 5);
        } catch (KryoException expected) {
            // Expected - third-party method invoked
        }
    }

    // Minimal implementation of NoFetchingInput to make test compile
    private static class NoFetchingInput {
        private final InputStream inputStream;

        public NoFetchingInput(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        public int read(byte[] bytes, int offset, int count) throws KryoException {
            if (bytes == null) {
                throw new IllegalArgumentException("bytes cannot be null.");
            }
            try {
                return inputStream.read(bytes, offset, count);
            } catch (IOException ex) {
                throw new KryoException(ex);
            }
        }
    }
}

