package org.apache.flink.api.java.typeutils.runtime.kryo;

import com.esotericsoftware.kryo.Kryo;
import com.esotericsoftware.kryo.io.Input;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class KryoSerializercopy_KryoreadObjectFikaTest {

    @Test
    public void testCopyTriggersKryoReadObject() throws Exception {
        // Create a real Kryo instance
        Kryo kryo = new Kryo();

        // Create a test object that will trigger the exception path
        NonCopyableObject original = new NonCopyableObject();

        // Create the serializer instance
        KryoSerializer<NonCopyableObject> serializer = 
            new KryoSerializer<>(NonCopyableObject.class, kryo.getConfiguration());

        // Use reflection to inject our Kryo instance that will throw exception
        java.lang.reflect.Field kryoField = KryoSerializer.class.getDeclaredField("kryo");
        kryoField.setAccessible(true);

        // Create a spy that will throw KryoException on copy()
        Kryo spyKryo = mock(Kryo.class);
        when(spyKryo.copy(original)).thenThrow(new com.esotericsoftware.kryo.KryoException());

        // Write should succeed
        when(spyKryo.writeObject(org.mockito.ArgumentMatchers.any(com.esotericsoftware.kryo.io.Output.class), 
                                 org.mockito.ArgumentMatchers.eq(original))).thenAnswer(invocation -> {
            ByteArrayOutputStream baout = new ByteArrayOutputStream();
            com.esotericsoftware.kryo.io.Output output = new com.esotericsoftware.kryo.io.Output(baout);
            kryo.writeObject(output, original);
            output.close();
            return null;
        });

        // Read should be called with real objects
        when(spyKryo.readObject(org.mockito.ArgumentMatchers.any(Input.class), 
                               org.mockito.ArgumentMatchers.any(Class.class))).thenAnswer(invocation -> {
            Input input = invocation.getArgument(0);
            Class<?> type = invocation.getArgument(1);
            return kryo.readObject(input, type);
        });

        kryoField.set(serializer, spyKryo);

        // This will trigger the exception path and call kryo.readObject()
        serializer.copy(original);
    }

    // Simple test class that cannot be copied directly by Kryo
    public static class NonCopyableObject {
        private String data = "test";

        public NonCopyableObject() {
        }

        public String getData() {
            return data;
        }

        public void setData(String data) {
            this.data = data;
        }
    }
}

