}

class DataInputViewStream extends java.io.InputStream {
    private final DataInputView dataInputView;
    private final byte[] singleByteBuffer = new byte[1];

    public DataInputViewStream(DataInputView dataInputView) {
        this.dataInputView = dataInputView;
    }

    @Override
    public int read() throws IOException {
        try {
            dataInputView.readFully(singleByteBuffer, 0, 1);
            return singleByteBuffer[0] & 0xFF;
        } catch (EOFException e) {
            return -1;
        }
    }

    @Override
    public int read(byte[] b, int off, int len) throws IOException {
        try {
            dataInputView.readFully(b, off, len);
            return len;
        } catch (EOFException e) {
            return -1;
        }
    }
}

class NoFetchingInput extends Input {
    public NoFetchingInput(java.io.InputStream inputStream) {
        super(inputStream);
    }
}

