    @Test
    public void testExtractZipFileWithPermissions() throws IOException {
        // Create a temporary zip file with a regular file entry
        Path tempDir = Files.createTempDirectory("zipTest");
        Path zipFile = tempDir.resolve("test.zip");
        Path targetDir = tempDir.resolve("extract");

        try (ZipOutputStream zos = new ZipOutputStream(Files.newOutputStream(zipFile))) {
            ZipEntry entry = new ZipEntry("test.txt");
            entry.setUnixMode(0644); // Set Unix mode to trigger getUnixMode() call
            zos.putNextEntry(entry);
            zos.write("test content".getBytes());
            zos.closeEntry();
        }

        // Call the method under test
        CompressionUtilsextractZipFileWithPermissions_ZipArchiveEntrygetUnixModeFikaTest.extractZipFileWithPermissions(
            zipFile.toString(),
            targetDir.toString()
        );

        // Cleanup
        Files.walk(tempDir)
             .sorted((a, b) -> -a.compareTo(b))
             .forEach(p -> {
                 try { Files.deleteIfExists(p); } catch (IOException ignored) {}
             });
    }

    // Copy of the method under test with its dependencies
    public static void extractZipFileWithPermissions(String zipFilePath, String targetPath) throws IOException {
        try (org.apache.commons.compress.archivers.zip.ZipFile zipFile = 
                new org.apache.commons.compress.archivers.zip.ZipFile(zipFilePath)) {
            java.util.Enumeration<org.apache.commons.compress.archivers.zip.ZipArchiveEntry> entries = zipFile.getEntries();
            boolean isUnix = isUnix();
            java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
            String canonicalTargetPath = new File(targetPath).getCanonicalPath() + File.separator;
            while (entries.hasMoreElements()) {
                org.apache.commons.compress.archivers.zip.ZipArchiveEntry entry = entries.nextElement();
                File outputFile = new File(canonicalTargetPath, entry.getName());
                if (!outputFile.getCanonicalPath().startsWith(canonicalTargetPath)) {
                    throw new IOException((("Expand " + entry.getName()) + " would create a file outside of ") + targetPath);
                }
                if (entry.isDirectory()) {
                    if (!outputFile.exists()) {
                        if (!outputFile.mkdirs()) {
                            throw new IOException(("Create dir: " + outputFile.getAbsolutePath()) + " failed!");
                        }
                    }
                } else {
                    File parentDir = outputFile.getParentFile();
                    if (!parentDir.exists()) {
                        if (!parentDir.mkdirs()) {
                            throw new IOException(("Create dir: " + outputFile.getAbsolutePath()) + " failed!");
                        }
                    }
                    if (entry.isUnixSymlink()) {
                        baos.reset();
                        org.apache.commons.compress.utils.IOUtils.copyBytes(zipFile.getInputStream(entry), baos);
                        Files.createSymbolicLink(outputFile.toPath(), new File(parentDir, baos.toString()).toPath());
                    } else if (outputFile.createNewFile()) {
                        FileOutputStream output = new FileOutputStream(outputFile);
                        org.apache.commons.compress.utils.IOUtils.copyBytes(zipFile.getInputStream(entry), output);
                    } else {
                        throw new IOException(("Create file: " + outputFile.getAbsolutePath()) + " failed!");
                    }
                }
                if (isUnix) {
                    // This is the target method call
                    int mode = entry.getUnixMode();
                    if (mode != 0) {
                        Path outputPath = Paths.get(outputFile.toURI());
                        java.util.Set<java.nio.file.attribute.PosixFilePermission> permissions = new java.util.HashSet<>();
                        addIfBitSet(mode, 8, permissions, java.nio.file.attribute.PosixFilePermission.OWNER_READ);
                        addIfBitSet(mode, 7, permissions, java.nio.file.attribute.PosixFilePermission.OWNER_WRITE);
                        addIfBitSet(mode, 6, permissions, java.nio.file.attribute.PosixFilePermission.OWNER_EXECUTE);
                        addIfBitSet(mode, 5, permissions, java.nio.file.attribute.PosixFilePermission.GROUP_READ);
                        addIfBitSet(mode, 4, permissions, java.nio.file.attribute.PosixFilePermission.GROUP_WRITE);
                        addIfBitSet(mode, 3, permissions, java.nio.file.attribute.PosixFilePermission.GROUP_EXECUTE);
                        addIfBitSet(mode, 2, permissions, java.nio.file.attribute.PosixFilePermission.OTHERS_READ);
                        addIfBitSet(mode, 1, permissions, java.nio.file.attribute.PosixFilePermission.OTHERS_WRITE);
                        addIfBitSet(mode, 0, permissions, java.nio.file.attribute.PosixFilePermission.OTHERS_EXECUTE);
                        try {
                            Files.setPosixFilePermissions(outputPath, permissions);
                        } catch (java.nio.file.NoSuchFileException e) {
                            // ignore
                        }
                    }
                }
            } 
        }
    }

    private static boolean isUnix() {
        return !System.getProperty("os.name").toLowerCase().contains("windows");
    }

    private static void addIfBitSet(int mode, int bitPosition, 
            java.util.Set<java.nio.file.attribute.PosixFilePermission> permissions,
            java.nio.file.attribute.PosixFilePermission permission) {
        if ((mode & (1 << bitPosition)) != 0) {
            permissions.add(permission);
        }
    }
}

