                        addIfBitSet(mode, 8, permissions, java.nio.file.attribute.PosixFilePermission.OWNER_READ);
                        addIfBitSet(mode, 7, permissions, java.nio.file.attribute.PosixFilePermission.OWNER_WRITE);
                        addIfBitSet(mode, 6, permissions, java.nio.file.attribute.PosixFilePermission.OWNER_EXECUTE);
                        addIfBitSet(mode, 5, permissions, java.nio.file.attribute.PosixFilePermission.GROUP_READ);
                        addIfBitSet(mode, 4, permissions, java.nio.file.attribute.PosixFilePermission.GROUP_WRITE);
                        addIfBitSet(mode, 3, permissions, java.nio.file.attribute.PosixFilePermission.GROUP_EXECUTE);
