package org.apache.flink.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.apache.flink.util.CompressionUtils.extractZipFileWithPermissions;

public class CompressionUtilsextractZipFileWithPermissions_ZipArchiveEntryisUnixSymlinkFikaTest {

    @Test
    public void testIsUnixSymlinkInvocation(@TempDir Path tempDir) throws IOException {
        // Create a temporary zip file with a symlink entry
        Path zipFilePath = tempDir.resolve("test.zip");
        Path targetDir = tempDir.resolve("target");
        Files.createDirectories(targetDir);

        // Create a simple text file to include in the zip
        Path textFile = tempDir.resolve("file.txt");
        Files.write(textFile, "Hello World".getBytes());

        // Create a symlink
        Path symlinkTarget = tempDir.resolve("target.txt");
        Files.write(symlinkTarget, "target content".getBytes());
        Path symlink = tempDir.resolve("link.txt");
        Files.createSymbolicLink(symlink, symlinkTarget);

        // Create zip file using java.util.zip
        java.util.zip.ZipOutputStream zos = new java.util.zip.ZipOutputStream(
            Files.newOutputStream(zipFilePath)
        );

        // Add regular file
        java.util.zip.ZipEntry fileEntry = new java.util.zip.ZipEntry("file.txt");
        zos.putNextEntry(fileEntry);
        zos.write(Files.readAllBytes(textFile));
        zos.closeEntry();

        // Add symlink entry - this will be treated as a regular file by java.util.zip
        // but ZipArchiveEntry.isUnixSymlink() will check the unix mode bits
        java.util.zip.ZipEntry linkEntry = new java.util.zip.ZipEntry("link.txt");
        // Set Unix permissions to indicate symlink (S_IFLNK = 0120000)
        linkEntry.setUnixMode(0120000 | 0777); // symlink with full permissions
        zos.putNextEntry(linkEntry);
        // Write the target path as the symlink content
        zos.write(symlinkTarget.toString().getBytes());
        zos.closeEntry();

        zos.close();

        // Execute the method which should invoke ZipArchiveEntry.isUnixSymlink()
        extractZipFileWithPermissions(zipFilePath.toString(), targetDir.toString());
    }
}

