/**
 * Loads the contents of the given YAML file into a map.
 *
 * @param file
 * 		the YAML file to load.
 * @return a non-null map representing the YAML content. If the file is empty or only contains
comments, an empty map is returned.
 * @throws FileNotFoundException
 * 		if the YAML file is not found.
 * @throws YamlEngineException
 * 		if the file cannot be parsed.
 * @throws IOException
 * 		if an I/O error occurs while reading from the file stream.
 */
@Nonnull
public static synchronized Map<String, Object> loadYamlFile(File file) throws Exception {
    try (FileInputStream inputStream = new FileInputStream(file)) {
        Map<String, Object> yamlResult = ((Map<String, Object>) (loader.loadFromInputStream(inputStream)));
        return yamlResult == null ? new HashMap<>() : yamlResult;
    } catch (FileNotFoundException e) {
        LOG.error("Failed to find YAML file", e);
        throw e;
    } catch (IOException | YamlEngineException e) {
        if (e instanceof MarkedYamlEngineException) {
            YamlEngineException exception = wrapExceptionToHiddenSensitiveData(((MarkedYamlEngineException) (e)));
            LOG.error("Failed to parse YAML configuration", exception);
            throw exception;
        } else {
            throw e;
        }
    }
}

