    private KryoSerializer createKryoSerializer() {
        // Create a KryoSerializer with default configuration
        Class<?> type = String.class;
        KryoSerializerConfig config = new KryoSerializerConfig();

        // Create default serializers map
        Map<Class<?>, SerializableSerializer<?>> defaultSerializers = new HashMap<>();
        defaultSerializers.put(Throwable.class, new SerializableSerializer<>(new JavaSerializer()));

        // Create default serializer classes map
        Map<Class<?>, Class<? extends Serializer<?>>> defaultSerializerClasses = new HashMap<>();

        // Create kryo registrations map
        Map<String, KryoRegistration> kryoRegistrations = new HashMap<>();

        // Create package registrar
        FlinkChillPackageRegistrar packageRegistrar = new FlinkChillPackageRegistrar();

        return new KryoSerializer(
            type,
            defaultSerializers,
            defaultSerializerClasses,
            kryoRegistrations,
            packageRegistrar,
            config
        );
    }

    // Helper classes to satisfy compilation
    private static class KryoSerializerConfig {
        // Empty configuration
    }

    private static class SerializableSerializer<T> {
        private final Serializer<T> serializer;

        public SerializableSerializer(Serializer<T> serializer) {
            this.serializer = serializer;
        }

        public Serializer<T> getSerializer() {
            return serializer;
        }
    }

    private static class KryoRegistration {
        // Empty registration class
    }

    private static class FlinkChillPackageRegistrar {
        public int getNextRegistrationId() {
            return 100;
        }
    }

    // Minimal KryoSerializer class to satisfy compilation
    private static class KryoSerializer {
        private Kryo kryo;
        private final Map<Class<?>, SerializableSerializer<?>> defaultSerializers;
        private final Map<Class<?>, Class<? extends Serializer<?>>> defaultSerializerClasses;
        private final Map<String, KryoRegistration> kryoRegistrations;
        private final FlinkChillPackageRegistrar flinkChillPackageRegistrar;

        public KryoSerializer(
            Class<?> type,
            Map<Class<?>, SerializableSerializer<?>> defaultSerializers,
            Map<Class<?>, Class<? extends Serializer<?>>> defaultSerializerClasses,
            Map<String, KryoRegistration> kryoRegistrations,
            FlinkChillPackageRegistrar flinkChillPackageRegistrar,
            KryoSerializerConfig config
        ) {
            this.defaultSerializers = defaultSerializers;
            this.defaultSerializerClasses = defaultSerializerClasses;
            this.kryoRegistrations = kryoRegistrations;
            this.flinkChillPackageRegistrar = flinkChillPackageRegistrar;
        }

        private Kryo getKryoInstance() {
            return new Kryo();
        }

        private void checkKryoInitialized() {
            if (this.kryo == null) {
                this.kryo = getKryoInstance();
                kryo.setReferences(true);
                kryo.addDefaultSerializer(Throwable.class, new JavaSerializer());
                for (Map.Entry<Class<?>, SerializableSerializer<?>> entry : defaultSerializers.entrySet()) {
                    kryo.addDefaultSerializer(entry.getKey(), entry.getValue().getSerializer());
                }
                for (Map.Entry<Class<?>, Class<? extends Serializer<?>>> entry : defaultSerializerClasses.entrySet()) {
                    kryo.addDefaultSerializer(entry.getKey(), entry.getValue());
                }
                KryoUtils.applyRegistrations(this.kryo, kryoRegistrations.values(), flinkChillPackageRegistrar != null ? flinkChillPackageRegistrar.getNextRegistrationId() : kryo.getNextRegistrationId());
                kryo.setRegistrationRequired(false);
                kryo.setClassLoader(Thread.currentThread().getContextClassLoader());
            }
        }
    }

