package org.apache.flink.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.GZIPOutputStream;

public class CompressionUtilsextractTarFileUsingJava_TarArchiveInputStreammethodFikaTest {

    @Test
    public void testExtractTarFileUsingJava(@TempDir Path tempDir) throws IOException {
        // Create a temporary tar file
        Path tarFile = tempDir.resolve("test.tar");
        createSimpleTarFile(tarFile);

        // Create target directory
        Path targetDir = tempDir.resolve("extract");
        Files.createDirectories(targetDir);

        // Call the method under test - this will invoke TarArchiveInputStream constructor
        extractTarFileUsingJava(tarFile.toString(), targetDir.toString(), false);
    }

    private static void createSimpleTarFile(Path tarPath) throws IOException {
        try (FileOutputStream fos = new FileOutputStream(tarPath.toFile());
             BufferedOutputStream bos = new BufferedOutputStream(fos);
             DataOutputStream dos = new DataOutputStream(bos)) {

            // Write a simple tar header for an empty file
            // File name
            byte[] fileName = "test.txt".getBytes();
            dos.write(fileName);
            for (int i = fileName.length; i < 100; i++) {
                dos.write(0);
            }

            // File mode
            for (int i = 0; i < 8; i++) {
                dos.write('0');
            }
            dos.write(0);

            // Owner ID
            for (int i = 0; i < 8; i++) {
                dos.write('0');
            }
            dos.write(0);

            // Group ID
            for (int i = 0; i < 8; i++) {
                dos.write('0');
            }
            dos.write(0);

            // File size (0 for empty file)
            for (int i = 0; i < 12; i++) {
                dos.write('0');
            }
            dos.write(0);

            // Last modification time
            for (int i = 0; i < 12; i++) {
                dos.write('0');
            }
            dos.write(0);

            // Checksum placeholder
            for (int i = 0; i < 8; i++) {
                dos.write(' ');
            }
            dos.write(0);

            // Type flag (regular file)
            dos.write('0');
            dos.write(0);

            // Link name
            for (int i = 0; i < 100; i++) {
                dos.write(0);
            }

            // Padding to 512 bytes
            for (int i = 0; i < 255; i++) {
                dos.write(0);
            }

            // End of archive markers
            for (int i = 0; i < 1024; i++) {
                dos.write(0);
            }
        }
    }

    private static void extractTarFileUsingJava(String inFilePath, String targetDirPath, boolean gzipped) throws IOException {
        try (InputStream fi = Files.newInputStream(Path.of(inFilePath));
             InputStream bi = new BufferedInputStream(fi);
             final org.apache.commons.compress.archivers.tar.TarArchiveInputStream tai = 
                 new org.apache.commons.compress.archivers.tar.TarArchiveInputStream(
                     gzipped ? new org.apache.commons.compress.compressors.gzip.GzipCompressorInputStream(bi) : bi)) {

            final File targetDir = new File(targetDirPath);
            org.apache.commons.compress.archivers.tar.TarArchiveEntry entry;
            while ((entry = tai.getNextTarEntry()) != null) {
                unpackEntry(tai, entry, targetDir);
            }
        }
    }

    private static void unpackEntry(org.apache.commons.compress.archivers.tar.TarArchiveInputStream tai,
