package org.apache.flink.util;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;

public class CompressionUtilsextractTarFileUsingJava_TarArchiveInputStreamcloseFikaTest {

    @Test
    public void testExtractTarFileUsingJava() throws Exception {
        @TempDir
        File tempDir;

        File tarFile = new File(tempDir, "test.tar");
        try (OutputStream os = Files.newOutputStream(tarFile.toPath());
             TarArchiveOutputStream taos = new TarArchiveOutputStream(os)) {

            TarArchiveEntry entry = new TarArchiveEntry("test.txt");
            entry.setSize(5);
            taos.putArchiveEntry(entry);
            taos.write("hello".getBytes());
            taos.closeArchiveEntry();
        }

        File targetDir = new File(tempDir, "extract");
        targetDir.mkdir();

        extractTarFileUsingJava(tarFile.getAbsolutePath(), targetDir.getAbsolutePath(), false);
    }

    private static void extractTarFileUsingJava(String inFilePath, String targetDirPath, boolean gzipped) throws IOException {
        try (InputStream fi = Files.newInputStream(Paths.get(inFilePath));
             InputStream bi = new BufferedInputStream(fi);
             final TarArchiveInputStream tai = new TarArchiveInputStream(gzipped ? new GzipCompressorInputStream(bi) : bi)) {

            final File targetDir = new File(targetDirPath);
            TarArchiveEntry entry;
            while ((entry = tai.getNextTarEntry()) != null) {
                unpackEntry(tai, entry, targetDir);
            }
        }
    }

    private static void unpackEntry(TarArchiveInputStream tai, TarArchiveEntry entry, File targetDir) throws IOException {
        File outputFile = new File(targetDir, entry.getName());
        if (entry.isDirectory()) {
            outputFile.mkdirs();
        } else {
            outputFile.getParentFile().mkdirs();
            try (OutputStream os = Files.newOutputStream(outputFile.toPath())) {
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = tai.read(buffer)) != -1) {
                    os.write(buffer, 0, bytesRead);
                }
            }
        }
    }
}

