        private static YamlEngineException wrapExceptionToHiddenSensitiveData(MarkedYamlEngineException exception) {
            StringBuilder lines = new StringBuilder();
            String context = exception.getContext();
            Optional<Mark> contextMark = exception.getContextMark();
            Optional<Mark> problemMark = exception.getProblemMark();
            String problem = exception.getProblem();
            if (context != null) {
                lines.append(context);
                lines.append("\n");
            }
            if (contextMark.isPresent() && (((((problem == null) || (!problemMark.isPresent())) || contextMark.get().getName().equals(problemMark.get().getName())) || (contextMark.get().getLine() != problemMark.get().getLine())) || (contextMark.get().getColumn() != problemMark.get().getColumn()))) {
                lines.append(hiddenSensitiveDataInMark(contextMark.get()));
