        try {
            kryo.writeClassAndObject(output, record);
            output.flush();
        } catch (KryoException ke) {
            // make sure that the Kryo output buffer is reset in case that we can recover from
            // the exception (e.g. EOFException which denotes buffer full)
            output.reset();
