package org.apache.flink.util;

import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;

public class CompressionUtilsunpackEntry_TarArchiveEntryisSymbolicLinkFikaTest {

    @Test
    public void testIsSymbolicLinkInvoked(@TempDir File tempDir) throws IOException {
        // Create a tar entry that is a symbolic link
        TarArchiveEntry entry = new TarArchiveEntry("link", TarArchiveEntry.LF_SYMLINK);
        entry.setLinkName("target");

        // Create a mock TarArchiveInputStream that won't be read from
        TarArchiveInputStream tis = new TarArchiveInputStream(
            Files.newInputStream(Paths.get("non-existent.tar"))
        ) {
            @Override
            public void close() {
                // Prevent actual file access
            }
        };

        try {
            // This will invoke entry.isSymbolicLink() as required
            CompressionUtils.unpackEntry(tis, entry, tempDir);
        } catch (IOException e) {
            // Expected since we're using a dummy input stream
            // No assertions needed
        } finally {
            tis.close();
        }
    }
}

