}

public IterationRuntimeUDFContext(JobInfo jobInfo, TaskInfo taskInfo, ClassLoader classloader, ExecutionConfig executionConfig, Map<String, Future<Path>> cpTasks, Map<String, Accumulator<?, ?>> accumulators, OperatorMetricGroup metrics) {
    super(jobInfo, taskInfo, classloader, executionConfig, cpTasks, accumulators, metrics);
}

public CompletedFuture(Path entry) {
    try {
        LocalFileSystem fs = ((LocalFileSystem) (FileSystem.getUnguardedFileSystem(entry.toUri())));
        result = (entry.isAbsolute()) ? new Path(entry.toUri().getPath()) : new Path(fs.getWorkingDirectory(), entry);
    } catch (Exception e) {
        throw new RuntimeException("DistributedCache supports only local files for Collection Environments");
    }
}

